```javascript
/**
 * @param {number[]} salary
 * @return {number}
 */
var average = function(salary) {
    let min = Infinity, max = -Infinity, sum = 0;
    for (const s of salary) {
        sum += s;
        if (s < min) min = s;
        if (s > max) max = s;
    }
    return (sum - min - max) / (salary.length - 2);
};
```

