/**
 * @param {number} left
 * @param {number} right
 * @return {string}
 */
var abbreviateProduct = function(left, right) {
    let count2 = 0, count5 = 0;
    let logSum = 0;

    // First pass: count factors of 2 and 5, and sum logarithms
    for (let i = left; i <= right; i++) {
        logSum += Math.log10(i);
        let temp = i;
        while (temp % 2 === 0) {
            count2++;
            temp /= 2;
        }
        while (temp % 5 === 0) {
            count5++;
            temp /= 5;
        }
    }

    const C = Math.min(count2, count5);
    const logP = logSum - C;
    const d = Math.floor(logP + 1e-9) + 1;

    if (d <= 10) {
        // Compute exact product after removing trailing zeros
        let R = 1;
        for (let i = left; i <= right; i++) {
            let temp = i;
            while (temp % 2 === 0) temp /= 2;
            while (temp % 5 === 0) temp /= 5;
            R *= temp;
        }
        let P = R;
        if (count2 > count5) {
            P *= Math.pow(2, count2 - count5);
        } else {
            P *= Math.pow(5, count5 - count2);
        }
        return P.toString() + "e" + C;
    } else {
        const MOD = 100000;
        let R_mod = 1;
        for (let i = left; i <= right; i++) {
            let temp = i;
            while (temp % 2 === 0) temp /= 2;
            while (temp % 5 === 0) temp /= 5;
            R_mod = (R_mod * temp) % MOD;
        }

        function modPow(base, exp, mod) {
            let res = 1;
            base %= mod;
            while (exp > 0) {
                if (exp % 2 === 1) res = (res * base) % mod;
                base = (base * base) % mod;
                exp = Math.floor(exp / 2);
            }
            return res;
        }

        let last5 = R_mod;
        if (count2 > count5) {
            last5 = (last5 * modPow(2, count2 - count5, MOD)) % MOD;
        } else {
            last5 = (last5 * modPow(5, count5 - count2, MOD)) % MOD;
        }
        let last5Str = last5.toString().padStart(5, '0');

        const frac = logP - Math.floor(logP);
        let first5 = Math.floor(Math.pow(10, frac + 4));
        if (first5 >= 100000) first5 = 99999;

        return first5 + "..." + last5Str + "e" + C;
    }
};
