/**
 * @param {string} s
 * @return {string[]}
 */
var ambiguousCoordinates = function(s) {
    const digits = s.slice(1, -1);
    const n = digits.length;

    const makeNumbers = (str) => {
        const res = [];
        const len = str.length;

        // Use the whole substring as an integer.
        if (str[0] !== '0' || len === 1) {
            res.push(str);
        }

        // Insert a decimal point.
        for (let i = 1; i < len; i++) {
            const left = str.slice(0, i);
            const right = str.slice(i);

            if ((left[0] !== '0' || left.length === 1) && right[right.length - 1] !== '0') {
                res.push(left + '.' + right);
            }
        }

        return res;
    };

    const ans = [];

    for (let i = 1; i < n; i++) {
        const leftPart = digits.slice(0, i);
        const rightPart = digits.slice(i);

        const leftNumbers = makeNumbers(leftPart);
        const rightNumbers = makeNumbers(rightPart);

        for (const x of leftNumbers) {
            for (const y of rightNumbers) {
                ans.push(`(${x}, ${y})`);
            }
        }
    }

    return ans;
};
```

