```javascript
/**
 * @param {number[][]} grid
 * @param {number[][]} hits
 * @return {number[]}
 */
var hitBricks = function(grid, hits) {
    const m = grid.length;
    const n = grid[0].length;
    const g = grid.map(row => row.slice());

    // Mark all hit cells as empty in the working grid
    for (const [r, c] of hits) {
        if (g[r][c] === 1) g[r][c] = 0;
    }

    const total = m * n;
    const top = total;
    const parent = new Array(total + 1);
    const size = new Array(total + 1).fill(1);
    for (let i = 0; i <= total; i++) parent[i] = i;
    size[top] = 0; // virtual top node has size 0

    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    const union = (x, y) => {
        let rx = find(x);
        let ry = find(y);
        if (rx === ry) return;
        if (size[rx] < size[ry]) {
            [rx, ry] = [ry, rx];
        }
        parent[ry] = rx;
        size[rx] += size[ry];
    };

    // Build initial union-find structure for remaining bricks
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (g[r][c] === 1) {
                const id = r * n + c;
                if (r === 0) union(id, top);
                if (r + 1 < m && g[r + 1][c] === 1) union(id, (r + 1) * n + c);
                if (c + 1 < n && g[r][c + 1] === 1) union(id, r * n + c + 1);
            }
        }
    }

    const res = new Array(hits.length).fill(0);
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    // Process hits in reverse
    for (let i = hits.length - 1; i >= 0; i--) {
        const [r, c] = hits[i];
        if (grid[r][c] === 0) {
            res[i] = 0;
            continue;
        }

        const id = r * n + c;
        const before = size[find(top)];

        // Restore the brick
        g[r][c] = 1;
        if (r === 0) union(id, top);
        for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] === 1) {
                union(id, nr * n + nc);
            }
        }

        const after = size[find(top)];
        res[i] = Math.max(0, after - before - 1);
    }

    return res;
};
```

