```javascript
var MKAverage = function(m, k) {
    this.m = m;
    this.k = k;
    this.MAX = 100000;

    this.countBIT = new Int32Array(this.MAX + 2);
    this.sumBIT = new Float64Array(this.MAX + 2);

    this.bitMask = 1;
    while ((this.bitMask << 1) <= this.MAX) {
        this.bitMask <<= 1;
    }

    this.queue = [];
    this.head = 0;
    this.totalSum = 0;
};

MKAverage.prototype._add = function(val, delta) {
    let i = val;
    while (i <= this.MAX) {
        this.countBIT[i] += delta;
        this.sumBIT[i] += delta * val;
        i += i & -i;
    }
};

MKAverage.prototype._queryCount = function(i) {
    let sum = 0;
    while (i > 0) {
        sum += this.countBIT[i];
        i -= i & -i;
    }
    return sum;
};

MKAverage.prototype._querySum = function(i) {
    let sum = 0;
    while (i > 0) {
        sum += this.sumBIT[i];
        i -= i & -i;
    }
    return sum;
};

MKAverage.prototype._findKth = function(k) {
    let pos = 0;
    let rem = k;
    let pw = this.bitMask;

    while (pw > 0) {
        const next = pos + pw;
        if (next <= this.MAX && this.countBIT[next] < rem) {
            pos = next;
            rem -= this.countBIT[next];
        }
        pw >>= 1;
    }

    return pos + 1;
};

MKAverage.prototype._sumSmallest = function(p) {
    if (p <= 0) return 0;

    const idx = this._findKth(p);
    const cntLess = this._queryCount(idx - 1);
    const sumLess = this._querySum(idx - 1);

    return sumLess + idx * (p - cntLess);
};

/** 
 * @param {number} num
 * @return {void}
 */
MKAverage.prototype.addElement = function(num) {
    this.queue.push(num);
    this.totalSum += num;
    this._add(num, 1);

    if (this.queue.length - this.head > this.m) {
        const old = this.queue[this.head++];
        this.totalSum -= old;
        this._add(old, -1);
    }
};

/**
 * @return {number}
 */
MKAverage.prototype.calculateMKAverage = function() {
    if (this.queue.length - this.head < this.m) {
        return -1;
    }

    const denom = this.m - 2 * this.k;
    const sumKSmallest = this._sumSmallest(this.k);
    const sumMKSmallest = this._sumSmallest(this.m - this.k);

    return Math.floor((sumMKSmallest - sumKSmallest) / denom);
};
```

