var numSmallerByFrequency = function(queries, words) {
    const f = (s) => {
        let minChar = 'z';
        for (const ch of s) {
            if (ch < minChar) minChar = ch;
        }
        let count = 0;
        for (const ch of s) {
            if (ch === minChar) count++;
        }
        return count;
    };

    const wordFreqs = words.map(f).sort((a, b) => a - b);
    const answer = [];

    for (const q of queries) {
        const target = f(q);
        let left = 0;
        let right = wordFreqs.length;

        while (left < right) {
            const mid = Math.floor((left + right) / 2);
            if (wordFreqs[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        answer.push(wordFreqs.length - left);
    }

    return answer;
};
```

