```javascript
var maxScore = function(nums) {
    const m = nums.length;
    const full = 1 << m;
    const dp = new Array(full).fill(-1);
    dp[0] = 0;

    const gcd = (a, b) => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    const gcdCache = Array.from({ length: m }, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            gcdCache[i][j] = gcd(nums[i], nums[j]);
        }
    }

    for (let mask = 0; mask < full; mask++) {
        if (dp[mask] === -1) continue;

        let used = 0;
        for (let i = 0; i < m; i++) {
            if (mask & (1 << i)) used++;
        }

        if (used % 2 !== 0) continue;

        const operation = used / 2 + 1;

        for (let i = 0; i < m; i++) {
            if (mask & (1 << i)) continue;

            for (let j = i + 1; j < m; j++) {
                if (mask & (1 << j)) continue;

                const nextMask = mask | (1 << i) | (1 << j);
                const score = dp[mask] + operation * gcdCache[i][j];

                if (score > dp[nextMask]) {
                    dp[nextMask] = score;
                }
            }
        }
    }

    return dp[full - 1];
};
```

