/**
 * @param {string} s
 * @param {number} k
 * @return {string}
 */
var licenseKeyFormatting = function(s, k) {
    let clean = "";
    for (let i = 0; i < s.length; i++) {
        const c = s[i];
        if (c !== '-') {
            clean += c.toUpperCase();
        }
    }

    const parts = [];
    let i = clean.length;

    while (i > 0) {
        const start = Math.max(0, i - k);
        parts.push(clean.slice(start, i));
        i = start;
    }

    return parts.reverse().join('-');
};
