```javascript
var numComponents = function(head, nums) {
    const set = new Set(nums);
    let count = 0;
    let inComponent = false;

    while (head !== null) {
        if (set.has(head.val)) {
            if (!inComponent) {
                count++;
                inComponent = true;
            }
        } else {
            inComponent = false;
        }
        head = head.next;
    }

    return count;
};
```

```javascript
/**
 * @param {number[]} flowers
 * @param {number} newFlowers
 * @param {number} target
 * @param {number} full
 * @param {number} partial
 * @return {number}
 */
var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const n = flowers.length;
    // Cap flowers at target
    let arr = flowers.map(f => Math.min(f, target));
    arr.sort((a, b) => a - b);

    let inc = [];
    let c0 = 0;
    for (let f of arr) {
        if (f < target) inc.push(f);
        else c0++;
    }

    // If all gardens are already complete
    if (inc.length === 0) {
        return n * full;
    }

    const m = inc.length;
    const pref = new Array(m + 1).fill(0);
    for (let i = 0; i < m; i++) {
        pref[i + 1] = pref[i] + inc[i];
    }

    // Precompute countLess[x] = number of elements in inc < x
    const countLess = new Array(target + 1).fill(0);
    let idx = 0;
    for (let x = 0; x <= target; x++) {
        while (idx < m && inc[idx] < x) idx++;
        countLess[x] = idx;
    }

    let ans = 0;
    let cost = 0;

    // Helper to find maximum possible minimum for first cnt incomplete gardens with rem flowers
    function maxMin(cnt, rem) {
        if (cnt === 0) return 0;
        let low = 0, high = target - 1;
        while (low < high) {
            let mid = Math.floor((low + high + 1) / 2);
            let p = Math.min(cnt, countLess[mid]);
            let c = mid * p - pref[p];
            if (c <= rem) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    // Try completing k largest incomplete gardens
    for (let k = 0; k <= m; k++) {
        if (k > 0) {
            cost += target - inc[m - k];
        }
        if (cost > newFlowers) break;
        let rem = newFlowers - cost;
        let cnt = m - k;
        let minVal = maxMin(cnt, rem);
        let beauty = (c0 + k) * full + minVal * partial;
        if (beauty > ans) ans = beauty;
    }

    return ans;
};
```

