```javascript
var maxCompatibilitySum = function(students, mentors) {
    const m = students.length;
    const n = students[0].length;
    const score = Array.from({ length: m }, () => Array(m).fill(0));

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < m; j++) {
            let s = 0;
            for (let k = 0; k < n; k++) {
                if (students[i][k] === mentors[j][k]) s++;
            }
            score[i][j] = s;
        }
    }

    const size = 1 << m;
    const dp = new Array(size).fill(-1);
    dp[0] = 0;

    for (let mask = 0; mask < size; mask++) {
        let i = 0;
        let x = mask;
        while (x) {
            i += x & 1;
            x >>= 1;
        }
        if (i >= m) continue;
        for (let j = 0; j < m; j++) {
            if ((mask & (1 << j)) === 0) {
                const next = mask | (1 << j);
                const val = dp[mask] + score[i][j];
                if (val > dp[next]) dp[next] = val;
            }
        }
    }

    return dp[size - 1];
};
