var maxSumTwoNoOverlap = function(nums, firstLen, secondLen) {
    const n = nums.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + nums[i];
    }

    const windowSum = (start, len) => prefix[start + len] - prefix[start];

    let best = 0;

    for (let i = 0; i + firstLen <= n; i++) {
        const firstSum = windowSum(i, firstLen);

        for (let j = 0; j + secondLen <= n; j++) {
            if (i + firstLen <= j || j + secondLen <= i) {
                best = Math.max(best, firstSum + windowSum(j, secondLen));
            }
        }
    }

    return best;
};
```

