```javascript
/**
 * @param {number[]} tasks
 * @param {number} sessionTime
 * @return {number}
 */
var minSessions = function(tasks, sessionTime) {
    const n = tasks.length;
    const totalMasks = 1 << n;
    const dpSessions = new Array(totalMasks).fill(Infinity);
    const dpRem = new Array(totalMasks).fill(-1);
    dpSessions[0] = 0;
    dpRem[0] = 0;

    for (let mask = 0; mask < totalMasks; mask++) {
        if (dpSessions[mask] === Infinity) continue;
        const s = dpSessions[mask];
        const rem = dpRem[mask];
        for (let i = 0; i < n; i++) {
            if (mask & (1 << i)) continue;
            const t = tasks[i];
            let ns, nrem;
            if (rem >= t) {
                ns = s;
                nrem = rem - t;
            } else {
                ns = s + 1;
                nrem = sessionTime - t;
            }
            const nmask = mask | (1 << i);
            if (ns < dpSessions[nmask] || (ns === dpSessions[nmask] && nrem > dpRem[nmask])) {
                dpSessions[nmask] = ns;
                dpRem[nmask] = nrem;
            }
        }
    }

    return dpSessions[totalMasks - 1];
};
```

