var removeInvalidParentheses = function(s) {
    let open = 0;
    let removeLeft = 0;
    let removeRight = 0;

    for (const ch of s) {
        if (ch === '(') {
            open++;
        } else if (ch === ')') {
            if (open > 0) {
                open--;
            } else {
                removeRight++;
            }
        }
    }
    removeLeft = open;

    const result = new Set();

    const dfs = (index, left, right, balance, current) => {
        if (index === s.length) {
            if (left === 0 && right === 0 && balance === 0) {
                result.add(current);
            }
            return;
        }

        const ch = s[index];

        if (ch === '(') {
            if (left > 0) {
                dfs(index + 1, left - 1, right, balance, current);
            }
            dfs(index + 1, left, right, balance + 1, current + ch);
        } else if (ch === ')') {
