                dfs(index + 1, left, right - 1, balance, current);
            }
            if (balance > 0) {
                dfs(index + 1, left, right, balance - 1, current + ch);
            }
        } else {
            dfs(index + 1, left, right, balance, current + ch);
        }
    };

    dfs(0, removeLeft, removeRight, 0, "");

    return Array.from(result);
};
