```javascript
var medianSlidingWindow = function(nums, k) {
    const sorted = Array.from(new Set(nums)).sort((a, b) => a - b);
    const indexMap = new Map();
    for (let i = 0; i < sorted.length; i++) {
        indexMap.set(sorted[i], i);
    }

    const compressed = nums.map(v => indexMap.get(v));
    const m = sorted.length;

    class Fenwick {
        constructor(n) {
            this.n = n;
            this.tree = new Array(n + 1).fill(0);
            let bit = 1;
            while (bit <= n) bit <<= 1;
            this.maxBit = bit >> 1;
        }

        add(i, delta) {
            for (i++; i <= this.n; i += i & -i) {
                this.tree[i] += delta;
            }
        }

        kth(k) {
            let idx = 0;
            for (let bit = this.maxBit; bit > 0; bit >>= 1) {
                const next = idx + bit;
                if (next <= this.n && this.tree[next] < k) {
                    idx = next;
                    k -= this.tree[next];
                }
            }
            return idx;
        }
    }

    const fw = new Fenwick(m);
    const result = [];
    const n = nums.length;

    for (let i = 0; i < n; i++) {
        fw.add(compressed[i], 1);

        if (i >= k) {
            fw.add(compressed[i - k], -1);
        }

        if (i >= k - 1) {
            if (k % 2 === 1) {
                const idx = fw.kth(Math.floor(k / 2) + 1);
                result.push(sorted[idx]);
            } else {
                const idx1 = fw.kth(k / 2);
                const idx2 = fw.kth(k / 2 + 1);
                result.push((sorted[idx1] + sorted[idx2]) / 2);
            }
        }
    }

    return result;
};
```

