```javascript
/**
 * @param {string[]} stickers
 * @param {string} target
 * @return {number}
 */
var minStickers = function(stickers, target) {
    const m = target.length;
    const full = (1 << m) - 1;

    // Map target letters to indices
    const letterIndex = new Map();
    for (let i = 0; i < m; i++) {
        if (!letterIndex.has(target[i])) {
            letterIndex.set(target[i], letterIndex.size);
        }
    }
    const d = letterIndex.size;
    const targetIndices = new Array(m);
    for (let i = 0; i < m; i++) {
        targetIndices[i] = letterIndex.get(target[i]);
    }

    // Preprocess stickers
    const stickerCounts = [];
    for (const s of stickers) {
        const counts = new Array(d).fill(0);
        let useful = false;
        for (const ch of s) {
            if (letterIndex.has(ch)) {
                counts[letterIndex.get(ch)]++;
                useful = true;
            }
        }
        if (useful) {
            stickerCounts.push(counts);
        }
    }

    if (stickerCounts.length === 0) return -1;

    const dist = new Int32Array(1 << m).fill(-1);
    dist[0] = 0;
    const queue = [0];
    let head = 0;
    const avail = new Array(d);

    while (head < queue.length) {
        const mask = queue[head++];
        const curDist = dist[mask];
        if (mask === full) return curDist;

        for (const counts of stickerCounts) {
            // Copy counts to avail
            for (let j = 0; j < d; j++) {
                avail[j] = counts[j];
            }
            let newMask = mask;
            for (let i = 0; i < m; i++) {
                if ((newMask & (1 << i)) === 0) {
                    const idx = targetIndices[i];
                    if (avail[idx] > 0) {
                        avail[idx]--;
                        newMask |= (1 << i);
                    }
                }
            }
            if (newMask !== mask && dist[newMask] === -1) {
                dist[newMask] = curDist + 1;
                queue.push(newMask);
            }
        }
    }

    return -1;
};
```

