/**
 * @param {string[]} grid
 * @return {number}
 */
var regionsBySlashes = function(grid) {
    const n = grid.length;
    const size = 3 * n;
    const wall = Array.from({ length: size }, () => new Array(size).fill(false));

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const ch = grid[i][j];
            const r = i * 3;
            const c = j * 3;

            if (ch === '/') {
                wall[r][c + 2] = true;
                wall[r + 1][c + 1] = true;
                wall[r + 2][c] = true;
            } else if (ch === '\\') {
                wall[r][c] = true;
                wall[r + 1][c + 1] = true;
                wall[r + 2][c + 2] = true;
            }
        }
    }

    const visited = Array.from({ length: size }, () => new Array(size).fill(false));
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    let regions = 0;

    for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
            if (!wall[i][j] && !visited[i][j]) {
                regions++;
                const queue = [[i, j]];
                visited[i][j] = true;
                let head = 0;

                while (head < queue.length) {
                    const [x, y] = queue[head++];

                    for (const [dx, dy] of dirs) {
                        const nx = x + dx;
                        const ny = y + dy;

                        if (
                            nx >= 0 && nx < size &&
                            ny >= 0 && ny < size &&
                            !wall[nx][ny] &&
                            !visited[nx][ny]
                        ) {
                            visited[nx][ny] = true;
                            queue.push([nx, ny]);
                        }
                    }
                }
            }
        }
    }

    return regions;
};
```

