```javascript
var StreamChecker = function(words) {
    this.root = { children: {}, isEnd: false };
    this.stream = [];
    this.maxLen = 0;

    for (const word of words) {
        let node = this.root;
        this.maxLen = Math.max(this.maxLen, word.length);

        for (let i = word.length - 1; i >= 0; i--) {
            const ch = word[i];
            if (!node.children[ch]) {
                node.children[ch] = { children: {}, isEnd: false };
            }
            node = node.children[ch];
        }

        node.isEnd = true;
    }
};

/** 
 * @param {character} letter
 * @return {boolean}
 */
StreamChecker.prototype.query = function(letter) {
    this.stream.push(letter);

    let node = this.root;
    const start = Math.max(0, this.stream.length - this.maxLen);

    for (let i = this.stream.length - 1; i >= start; i--) {
        const ch = this.stream[i];
        node = node.children[ch];

        if (!node) {
            return false;
        }

        if (node.isEnd) {
            return true;
        }
    }

    return false;
};
```

