var sortByBits = function(arr) {
    const popcount = (n) => {
        let count = 0;
        while (n) {
            n &= n - 1;
            count++;
        }
        return count;
    };

    return arr.sort((a, b) => {
        const ca = popcount(a);
        const cb = popcount(b);
        if (ca !== cb) return ca - cb;
        return a - b;
    });
};
```

