Code structure:
var earliestAndLatest = function(n, firstPlayer, secondPlayer) {
    const memo = new Map();
    function dfs(n, p1, p2) {
        // p1 < p2
        if (p1 + p2 > n + 1) {
            const a = n + 1 - p2;
            const b = n + 1 - p1;
            p1 = a;
            p2 = b;
        }
        const key = n + ',' + p1 + ',' + p2;
        if (memo.has(key)) return memo.get(key);
        if (p1 + p2 === n + 1) {
            const res = [1, 1];
            memo.set(key, res);
            return res;
        }
        let min = Infinity, max = -Infinity;
        // collect non-special pairs count
        let m = 0;
        const half = Math.floor(n / 2);
        for (let i = 1; i <= half; i++) {
            const j = n + 1 - i;
            if (i === p1 || j === p1 || i === p2 || j === p2) continue;
            m++;
        }
        const totalMasks = 1 << m;
        for (let mask = 0; mask < totalMasks; mask++) {
            const alive = new Array(n + 1).fill(false);
            alive[p1] = true;
            alive[p2] = true;
            let bit = 0;
            for (let i = 1; i <= half; i++) {
                const j = n + 1 - i;
                if (i === p1 || j === p1 || i === p2 || j === p2) {
                    // special wins; already alive
                } else {
                    if (mask & (1 << bit)) {
                        alive[i] = true;
                    } else {
                        alive[j] = true;
                    }
                    bit++;
                }
            }
            if (n % 2 === 1) {
                const mid = (n + 1) >> 1;
                alive[mid] = true;
            }
            let n2 = 0, q1 = 0, q2 = 0;
            for (let pos = 1; pos <= n; pos++) {
                if (alive[pos]) {
                    n2++;
                    if (pos === p1) q1 = n2;
                    if (pos === p2) q2 = n2;
                }
            }
            const sub = dfs(n2, q1, q2);
            if (sub[0] + 1 < min) min = sub[0] + 1;
            if (sub[1] + 1 > max) max = sub[1] + 1;
        }
        const res = [min, max];
        memo.set(key, res);
        return res;
    }
    return dfs(n, firstPlayer, secondPlayer);
};

