```javascript
var getCoprimes = function(nums, edges) {
    const n = nums.length;
    const MAX = 50;

    const gcd = (a, b) => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    const cop = Array.from({ length: MAX + 1 }, () => new Array(MAX + 1).fill(false));
    for (let i = 1; i <= MAX; i++) {
        for (let j = 1; j <= MAX; j++) {
            cop[i][j] = gcd(i, j) === 1;
        }
    }

    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const ans = new Array(n).fill(-1);
    const last = new Array(MAX + 1).fill(-1);
    const depth = new Array(n).fill(0);

    const stack = [[0, -1, 0, 0, -1]];

    while (stack.length > 0) {
        const ev = stack.pop();
        const u = ev[0];
        const p = ev[1];
        const d = ev[2];
        const state = ev[3];

        if (state === 0) {
            const val = nums[u];
            let best = -1;
            let bestDepth = -1;

            for (let v = 1; v <= MAX; v++) {
                const idx = last[v];
                if (idx !== -1 && cop[val][v]) {
                    const dep = depth[idx];
                    if (dep > bestDepth) {
                        bestDepth = dep;
                        best = idx;
                    }
                }
            }

            ans[u] = best;
            depth[u] = d;

            const prev = last[val];
            stack.push([u, p, d, 1, prev]);
            last[val] = u;

            const neighbors = adj[u];
            for (let i = 0; i < neighbors.length; i++) {
                const nei = neighbors[i];
                if (nei !== p) {
                    stack.push([nei, u, d + 1, 0, -1]);
                }
            }
        } else {
            const prev = ev[4];
            last[nums[u]] = prev;
        }
    }

    return ans;
};
```

