/**
 * @param {number} rows
 * @param {number} cols
 * @param {number} rStart
 * @param {number} cStart
 * @return {number[][]}
 */
var spiralMatrixIII = function(rows, cols, rStart, cStart) {
    const total = rows * cols;
    const result = [[rStart, cStart]];
    if (total === 1) return result;

    const dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    let dir = 0;
    let steps = 1;
    let r = rStart;
    let c = cStart;

    while (result.length < total) {
        for (let i = 0; i < steps; i++) {
            r += dirs[dir][0];
            c += dirs[dir][1];

            if (r >= 0 && r < rows && c >= 0 && c < cols) {
                result.push([r, c]);
                if (result.length === total) {
                    return result;
                }
            }
        }

        dir = (dir + 1) % 4;
        if (dir % 2 === 0) {
            steps++;
        }
    }

    return result;
};
```

