var isSolvable = function(words, result) {
    const leading = new Set();
    for (const w of words) leading.add(w[0]);
    leading.add(result[0]);

    const maxLen = Math.max(result.length, ...words.map(w => w.length));
    const colCounts = [];
    for (let col = 0; col < maxLen; col++) {
        const counts = new Map();
        for (const w of words) {
            const idx = w.length - 1 - col;
            if (idx >= 0) {
                const ch = w[idx];
                counts.set(ch, (counts.get(ch) || 0) + 1);
            }
        }
        colCounts.push(counts);
    }
    const targets = [];
    for (let col = 0; col < maxLen; col++) {
        const idx = result.length - 1 - col;
        targets.push(idx >= 0 ? result[idx] : null);
    }

    const digit = new Map();
    const used = new Array(10).fill(false);

    function dfs(col, carry) {
        if (col === maxLen) {
            return carry === 0;
        }
        const counts = colCounts[col];
        const targetChar = targets[col];
        const unassigned = [];
        for (const ch of counts.keys()) {
            if (!digit.has(ch)) unassigned.push(ch);
        }
        // Optional: sort by count descending? Not necessary.
        function assign(i, sum) {
            if (i === unassigned.length) {
                const targetDigit = sum % 10;
                const nextCarry = Math.floor(sum / 10);
                if (targetChar === null) {
                    if (targetDigit !== 0) return false;
                    return dfs(col + 1, nextCarry);
                }
                if (digit.has(targetChar)) {
                    if (digit.get(targetChar) !== targetDigit) return false;
                    return dfs(col + 1, nextCarry);
                }
                if (used[targetDigit]) return false;
                if (targetDigit === 0 && leading.has(targetChar)) return false;
                digit.set(targetChar, targetDigit);
                used[targetDigit] = true;
                const ok = dfs(col + 1, nextCarry);
                used[targetDigit] = false;
                digit.delete(targetChar);
                return ok;
            }
            const ch = unassigned[i];
            const cnt = counts.get(ch);
            for (let d = 0; d <= 9; d++) {
                if (used[d]) continue;
                if (d === 0 && leading.has(ch)) continue;
                digit.set(ch, d);
                used[d] = true;
                if (assign(i + 1, sum + d * cnt)) {
                    used[d] = false;
                    digit.delete(ch);
                    return true;
                }
                used[d] = false;
                digit.delete(ch);
            }
            return false;
        }
        return assign(0, carry);
    }

    return dfs(0, 0);
};
```

